function allSpecialPresets(){return [...FAMILY_SYMBOLIC_PRESETS,...INDIVIDUAL_PRESETS,...ENERGETIC_PRESETS]}
function isHypotheticalTheme(session){return session?.symbolicFrame==='hypothetical' || /(brujer[ií]a|mal de ojo|energ[ií]a externa|influencia externa|hechizo|carga externa|ambiente pesado)/i.test(session?.topic||'')}
function isAddictionTheme(session){return session?.symbolicFrame==='wellbeing' || /(adicci[oó]n|consumo|compulsi[oó]n|sustancia|alcohol|droga|apuesta|impulso compulsivo)/i.test(session?.topic||'')}
function themeContextSentence(session){
  const intuitive=isIntuitiveSession(session);
  if(isHypotheticalTheme(session)) return ' En este tema, Campo trata la idea de influencia externa como una hipótesis simbólica o una forma de nombrar tu experiencia; la disposición no identifica ni demuestra una causa externa.';
  if(isAddictionTheme(session)) return ' En un tema de adicción, consumo o compulsión, esta lectura explora relaciones, impulsos, necesidades, consecuencias, límites y recursos sin asumir una causa única.';
  if(intuitive) return ' Las figuras intuitivas de esta sesión pueden funcionar como personajes simbólicos para dar forma a vacíos o sensaciones; no necesitan corresponder a personas ni acontecimientos reales.';
  return '';
}

