  route: 'home', data: {active:null,sessions:[]}, settings: {...DEFAULT_SETTINGS},
  locked: false, unlockError:'', wizardStep:'type', selectedTemplate:null,
  placementMode:'physical', observationIndex:0, observationReturn:'placement', movementMode:'offer',
  selectedPieceId:null, movementBefore:null, phraseIndex:0, closeStep:0, integrationStep:0,
  historySessionId:null, modal:null, toast:null, ambientNode:null, photoUrls:{}, crisisText:'',
