  setSessionChoice(field,val){ensureActive()[field]=val;persist();render()},
  setSessionSoundscape(v){const s=ensureActive();s.soundscape=v;if(state.settings.ambient){startAmbient(v)}persist();render()},
  previewSoundscape(){const s=ensureActive();startAmbient(s.soundscape||state.settings.ambientScene||'cosmic',true);toast(`Ambiente: ${soundscapeLabel(s.soundscape||state.settings.ambientScene)}`)},
  previewSessionVoice(){const s=ensureActive();if(s.voiceRole==='silent'){toast('Esta constelación está en modo sin voz.');return}speak('Estoy aquí. Cuando estés listo, continuamos con tu constelación.',s.voiceRole==='companion'?'companion':'guide')},
  prepareReps(){const s=ensureActive();if(!s.pieces.length){let labels=TYPE_DEFS[s.type].reps.slice();if(s.pieceCount==='2-3')labels=labels.slice(0,3);else if(s.pieceCount==='7-10')labels=[...labels,'Límite','Próximo paso','Apoyo'];s.pieces=labels.map(piece)}state.wizardStep='reps';persist();render()},
  toggleFamilyRep(label){const s=ensureActive();const found=s.pieces.find(p=>p.label===label);if(found){if(s.pieces.length<=2){toast('Conserva al menos dos representantes.');return}s.pieces=s.pieces.filter(p=>p.id!==found.id)}else{if(s.pieces.length>=10){toast('Máximo 10 piezas por sesión.');return}{const p=FAMILY_GROUPS.intuitive.includes(label)?intuitivePiece(label,s.pieces.length):piece(label,s.pieces.length);s.pieces.push(p);if(p.hypothetical)s.familyUnknownMode=true}}persist();render()},
  renameRep(id,val){const p=ensureActive().pieces.find(x=>x.id===id);if(p)p.label=val;persist()},
  deleteRep(id){const s=ensureActive();if(s.pieces.length<=2){toast('Conserva al menos dos representantes.');return}s.pieces=s.pieces.filter(x=>x.id!==id);persist();render()},
