  async beginSession(){const s=ensureActive();s.pieces=s.pieces.filter(p=>p.label.trim());if(s.pieces.length<2){toast('Necesitas al menos dos representantes.');return}s.stage='opening';s.placementIndex=0;state.placementMode='physical';state.route='session';if(state.settings.ambient&&s.soundscape!=='silence')startAmbient(s.soundscape||state.settings.ambientScene||'cosmic');await persist();haptic();render()},
