  interpretRelation(id){const s=ensureActive();const a=s.pieces.find(x=>x.id===state.relationSourceId),b=s.pieces.find(x=>x.id===id);state.modal=null;if(!a||!b)return;readingRecord(`${a.label} ↔ ${b.label}`,relationReading(a,b,state.interpretationVariant),'relation',[a.id,b.id])},
  interpretField(){const s=ensureActive();readingRecord('Lectura integrada del campo',fieldReading(s,state.interpretationVariant),'field',placedPieces(s).map(p=>p.id))},
